import type { WorkspaceTab } from '../types/procurement';

export interface HelpProblem {
  symptom: string;
  cause: string;
  fix: string;
}

/**
 * A numbered marker drawn on a real screenshot. `find` is the visible button,
 * field label or text on that screen. Numbers match the steps list.
 */
export interface HelpCallout {
  n: number;
  find: string;
  label: string;
}

export interface HelpShot {
  /** File in src/assets/help (generated by scripts/capture-help.cjs) */
  file: string;
  caption: string;
  /** Workspace page to show (sidebar label is looked up from it) */
  page: WorkspaceTab;
  /** Opens a dialog before capturing */
  open?: 'importReview' | 'unlockDialog' | 'amendMode' | 'selectAllJobs';
  /** Seeds an issued document so issued-only controls appear */
  issued?: boolean;
  /** Capture window height in px when the screen is taller than the default (900) */
  height?: number;
  /** Scales the page so a long screen fits in one capture */
  zoom?: number;
  callouts: HelpCallout[];
}

export interface HelpTopic {
  id: string;
  title: string;
  summary: string;
  keywords: string[];
  /** Numbered steps. Step n matches marker n on the screenshots. */
  steps: string[];
  checklist?: string[];
  problems: HelpProblem[];
  shots: HelpShot[];
}

